"""Random lines of mixed-case words separated by one or more spaces."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    parts = [rng.choice(["", " ", "  "]) if rng.random() < 0.3 else ""]
    for _ in range(rng.randint(1, 4)):
        word = "".join(rng.choice("abcdefXYZ") for _ in range(rng.randint(1, 6)))
        parts.append("".join(c.upper() if rng.random() < 0.5 else c for c in word))
        parts.append(" " * rng.randint(1, 3))
    return {"name": "a line of words #%d" % index, "stdin": "".join(parts) + "\n"}
